@Test
public void testDeprecated() throws ParseException {
    final Set<Option> handler = new HashSet<>();
    parser = DefaultParser.builder().setDeprecatedHandler(handler::add).build();
    final Option opt1 = Option.builder().option("d1").deprecated().build();
    // @formatter:off
    final Option opt2 = Option.builder().option("d2").deprecated(DeprecatedAttributes.builder()
            .setForRemoval(true)
            .setSince("1.0")
            .setDescription("Do this instead.").get()).build();
    // @formatter:on
    final Option opt3 = Option.builder().option("a").build();
    // @formatter:off
    final CommandLine cl = parser.parse(new Options()
            .addOption(opt1)
            .addOption(opt2)
            .addOption(opt3),
            new String[] {"-d1", "-d2", "-a"});
    // @formatter:on
    // Trigger handler:
    assertTrue(cl.hasOption(opt1.getOpt()));
    assertTrue(cl.hasOption(opt2.getOpt()));
    assertTrue(cl.hasOption(opt3.getOpt()));
    // Assert handler was triggered
    assertTrue(handler.contains(opt1));
    assertTrue(handler.contains(opt2));
    assertFalse(handler.contains(opt3));
}

proposals.refactored:
private static class TestData {
    CommandLine cl;
    Option opt1;
    Option opt2;
    Option opt3;
    Set<Option> handler;
}

private TestData setupDeprecatedParsing() {
    Set<Option> handler = new HashSet<>();
    DefaultParser localParser = DefaultParser.builder()
            .setDeprecatedHandler(handler::add)
            .build();

    Option opt1 = Option.builder()
            .option("d1")
            .deprecated()
            .build();

    Option opt2 = Option.builder()
            .option("d2")
            .deprecated(DeprecatedAttributes.builder()
                    .setForRemoval(true)
                    .setSince("1.0")
                    .setDescription("Do this instead.")
                    .get())
            .build();

    Option opt3 = Option.builder()
            .option("a")
            .build();

    CommandLine cl = assertDoesNotThrow(() ->
            localParser.parse(new Options()
                    .addOption(opt1)
                    .addOption(opt2)
                    .addOption(opt3),
                    new String[] {"-d1", "-d2", "-a"}),
            "Parsing command line should not throw an exception");

    TestData data = new TestData();
    data.handler = handler;
    data.cl = cl;
    data.opt1 = opt1;
    data.opt2 = opt2;
    data.opt3 = opt3;
    return data;
}

@Test
public void testDeprecated_OptionParsing() {
    TestData data = setupDeprecatedParsing();
    assertTrue(data.cl.hasOption(data.opt1.getOpt()), "Deprecated option d1 should be recognized");
    assertTrue(data.cl.hasOption(data.opt2.getOpt()), "Deprecated option d2 should be recognized");
    assertTrue(data.cl.hasOption(data.opt3.getOpt()), "Non‑deprecated option a should be recognized");
}

@Test
public void testDeprecated_HandlerInvocation() {
    TestData data = setupDeprecatedParsing();
    assertTrue(data.handler.contains(data.opt1), "Handler should be invoked for deprecated option d1");
    assertTrue(data.handler.contains(data.opt2), "Handler should be invoked for deprecated option d2");
    assertFalse(data.handler.contains(data.opt3), "Handler should not be invoked for non‑deprecated option a");
}

