@Test public void supportsClone() {
    Document doc = org.jsoup.Jsoup.parse("<div class=foo>Text</div>");
    Element el = doc.select("div").first();
    assertTrue(el.hasClass("foo"));

    Element elClone = doc.clone().select("div").first();
