 * @return a {@link Document} parsed from the sample HTML containing a <pre> element.
 */
private Document setupTestKeepsPreTextAtDepth() {
    String html = "<pre><code><span><b>code\n\ncode</b></span></code></pre>";
    return Jsoup.parse(html);
}
